import sys

def hole_palindromic_suffix_start(s: str) -> int:
    """Return the smallest index i in [0, len(s)] such that s[i:] is a palindrome.

    Must satisfy:
    - The result i is in the range 0 <= i <= len(s).
    - s[i:] reads the same forwards and backwards.
    - No smaller index j < i has s[j:] as a palindrome.
    - For s == "", return 0 (the empty suffix is a palindrome).
    """
    raise NotImplementedError

def _reverse(text: str) -> str:
    return text[::-1]

def make_palindrome(s: str) -> str:
    """Return the shortest palindrome that starts with s, formed by appending characters to its end."""
    if not isinstance(s, str):
        raise TypeError('make_palindrome expects a str')
    start = hole_palindromic_suffix_start(s)
    return s + _reverse(s[:start])

def check_invariants() -> None:
    assert make_palindrome('') == ''
    assert make_palindrome('a') == 'a'
    assert make_palindrome('ab') == 'aba'
    assert make_palindrome('abc') == 'abcba'
    assert make_palindrome('race') == 'racecar'
    assert make_palindrome('aacecaaa') == 'aacecaaacecaa'
    assert make_palindrome('abcd').startswith('abcd')
    assert make_palindrome('abcd') == make_palindrome('abcd')[::-1]
if __name__ == '__main__':
    for arg in sys.argv[1:]:
        print(make_palindrome(arg))


