import sys
from typing import List, Set, Tuple
Cell = Tuple[int, int]

def _neighbors(n: int, cell: Cell) -> List[Cell]:
    """Return the in-bounds edge-adjacent cells of `cell` in an n x n grid."""
    r, c = cell
    out: List[Cell] = []
    for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
        nr, nc = (r + dr, c + dc)
        if 0 <= nr < n and 0 <= nc < n:
            out.append((nr, nc))
    return out

def hole_start_frontier(grid: List[List[int]]) -> Tuple[int, Set[Cell]]:
    """Return (value, cells) for the first step of the path.

    `grid` is a non-empty N x N list of lists holding distinct values 1..N*N.
    `value` must be the smallest value the path can possibly start with
    (the minimum over all grid entries). `cells` must be the set of (row, col)
    positions holding `value`. Must be non-empty.
    """
    raise NotImplementedError

def hole_next_frontier(grid: List[List[int]], frontier: Set[Cell]) -> Tuple[int, Set[Cell]]:
    """Return (value, new_frontier) for the next step of the path.

    `frontier` is a non-empty set of (row, col) cells that are the possible
    current endpoints of the lexicographically smallest prefix so far.
    Let C be the union of _neighbors(n, f) over all f in `frontier`.
    `value` must be the minimum of grid[r][c] over (r, c) in C.
    `new_frontier` must be the set of (r, c) in C with grid[r][c] == value.
    Must be non-empty.
    """
    raise NotImplementedError

def minPath(grid: List[List[int]], k: int) -> List[int]:
    """Return the lexicographically smallest list of values along a path of k cells.

    Cells are edge-adjacent (up/down/left/right) and may be revisited.
    Raises ValueError if k < 1.
    """
    if k < 1:
        raise ValueError('k must be at least 1')
    value, frontier = hole_start_frontier(grid)
    result: List[int] = [value]
    for _ in range(k - 1):
        value, frontier = hole_next_frontier(grid, frontier)
        result.append(value)
    return result

def _read_input(text: str) -> Tuple[List[List[int]], int]:
    """Parse input: first line 'N k', then N rows of N integers each."""
    tokens = text.split()
    n, k = (int(tokens[0]), int(tokens[1]))
    values = [int(t) for t in tokens[2:2 + n * n]]
    grid = [values[i * n:(i + 1) * n] for i in range(n)]
    return (grid, k)

def _format_output(path: List[int]) -> str:
    """Format the path as space-separated values."""
    return ' '.join((str(v) for v in path))

def check_invariants() -> None:
    """Assertions about the public API behaviour of minPath."""
    g3 = [[1, 2, 3], [4, 5, 6], [7, 8, 9]]
    assert minPath(g3, 3) == [1, 2, 1]
    assert minPath([[5, 9, 3], [4, 1, 6], [7, 8, 2]], 1) == [1]
    assert minPath([[1, 2], [3, 4]], 4) == [1, 2, 1, 2]
    assert minPath([[1]], 5) == [1, 1, 1, 1, 1]
    assert len(minPath(g3, 7)) == 7
    assert minPath(g3, 2) == [1, 2]

def main() -> None:
    grid, k = _read_input(sys.stdin.read())
    print(_format_output(minPath(grid, k)))
if __name__ == '__main__':
    main()


