def hole_start_frontier(grid: List[List[int]]) -> Tuple[int, Set[Cell]]:
    """Return (value, cells) for the first step of the path."""
    best = None
    cells: Set[Cell] = set()
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if best is None or v < best:
                best = v
                cells = {(r, c)}
            elif v == best:
                cells.add((r, c))
    return (best, cells)

def hole_next_frontier(grid: List[List[int]], frontier: Set[Cell]) -> Tuple[int, Set[Cell]]:
    """Return (value, new_frontier) for the next step of the path."""
    n = len(grid)
    candidates: Set[Cell] = set()
    for f in frontier:
        for nb in _neighbors(n, f):
            candidates.add(nb)
    best = min((grid[r][c] for r, c in candidates))
    new_frontier = {(r, c) for r, c in candidates if grid[r][c] == best}
    return (best, new_frontier)

