      2.0 < gpa <= 2.3    -> "C+"
      1.7 < gpa <= 2.0    -> "C"
      1.3 < gpa <= 1.7    -> "C-"
      1.0 < gpa <= 1.3    -> "D+"
      0.7 < gpa <= 1.0    -> "D"
      0.0 < gpa <= 0.7    -> "D-"
      gpa == 0.0          -> "E"
    Return exactly one of these twelve-plus-one strings, unchanged in case.
    """
    raise NotImplementedError

def numerical_letter_grade(grades: Sequence[float]) -> list[str]:
    """Convert a sequence of GPAs into a list of letter grades.

    Returns a new list with one letter grade per input GPA, in the same order.
    Raises ValueError naming the offending index if any GPA fails
    hole_is_valid_gpa.
    """
    letters: list[str] = []
    for index, gpa in enumerate(grades):
        if not hole_is_valid_gpa(gpa):
            raise ValueError(f'invalid GPA at index {index}: {gpa!r}')
        letters.append(hole_letter_for_gpa(gpa))
    return letters

