"""Flatten arbitrarily nested lists and tuples.

Strings (and other non-list/tuple values) are treated as atomic items.
"""

def hole_is_nested(item) -> bool:
    """Return True if `item` must be expanded further, False if it is an atomic leaf.

    Must return True exactly when `item` is an instance of list or tuple.
    Must return False for every other value, including str, bytes, and dict.
    """
    raise NotImplementedError

def hole_combine(prefix: list, item) -> list:
    """Return a new list equal to `prefix` followed by the leaf `item`.

    Must not mutate `prefix`. For a leaf `item`, the result is
    prefix + [item]. The result must be a plain list.
    """
    raise NotImplementedError

def flatten(nested) -> list:
    """Return a single flat list of all leaf values in `nested`, in order.

    `nested` may be a list or tuple containing further lists/tuples to any depth.
    Strings and other non-sequence values are kept whole as leaves.
    """
    if not hole_is_nested(nested):
        return hole_combine([], nested)
    result = []
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if hole_is_nested(item):
            stack.append(iter(item))
        else:
            result = hole_combine(result, item)
    return result

def _format(values: list) -> str:
    """Render a flat list as a single line for display."""
    return ', '.join((repr(v) for v in values))

def main() -> None:
    samples = [[1, [2, 3], (4, [5, (6,)])], ['ab', ('cd', ['ef'])], (), [[], [[]], 7]]
    for sample in samples:
        print(f'{sample!r} -> [{_format(flatten(sample))}]')

