def hole_split_fields(line: str) -> list[str]:
    """Split a config line into raw field strings.

    Input: a non-empty string (already stripped by the caller), e.g.
        'a=1; debug; msg="hi; there"'
    Must return: a list of raw field strings, one per logical field, in
    their original order. Fields are separated by ';'. A ';' that appears
    inside a double-quoted region (between an opening '"' and its closing
