        ['a=1', 'debug', 'msg="hi; there"']
    """
    raise NotImplementedError

def hole_parse_field(field: str) -> tuple[str, Union[str, bool]]:
    """Interpret one non-empty, stripped raw field as a (key, value) pair.

    Input: a non-empty string with no leading/trailing whitespace.
    Must return a tuple (key, value) where:
      - If the field contains no '=', it is a bare key: return
        (field, True).
      - Otherwise split on the FIRST '=': the key is the text before it,
        and the value is the text after it. Strip whitespace from key and
        value. If the value is wrapped in a matching pair of double quotes,
        remove exactly those two outer quote characters. Return the value
        as a str (never converted to int or other types).
    Examples that must hold:
        'debug'          -> ('debug', True)
        'a=1'            -> ('a', '1')
        'msg="hi; there"' -> ('msg', 'hi; there')
        'x=""'           -> ('x', '')
    """
    raise NotImplementedError

def parse_kv(line: str) -> dict[str, Union[str, bool]]:
    """Parse a config line such as 'a=1; debug; msg="hi; there"' into a dict.

    Bare keys map to True. Key=value entries map to their string value with
    surrounding double quotes removed. Quoted values may contain semicolons.
    Empty or whitespace-only fields are ignored. Raises TypeError if line is
    not a str.
