            op = self._advance().value
            rhs = self._term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def _term(self) -> int:
        value = self._unary()
        while self._is_op(self._peek(), ('*', '/', '%')):
            op = self._advance().value
            rhs = self._unary()
            if op == '*':
                value = value * rhs
            elif op == '/':
                value = hole_c_div(value, rhs)
            else:
                value = hole_c_mod(value, rhs)
        return value

    def _unary(self) -> int:
        if self._is_op(self._peek(), ('-',)):
            self._advance()
            return -self._unary()
        return self._power()

    def _power(self) -> int:
        base = self._primary()
        if self._is_op(self._peek(), ('^',)):
            self._advance()
            exp = self._unary()
            return hole_pow(base, exp)
        return base

    def _primary(self) -> int:
        tok = self._advance()
