from typing import Callable, Dict, Hashable, Iterable, List, Optional, Set, Tuple
Node = Hashable
Adjacency = Dict[Node, Set[Node]]
Assignment = Dict[Node, int]
PickFn = Callable[[List[Node], Assignment, Adjacency, int], Node]

def _build_adjacency(nodes: Iterable[Node], edges: Iterable[Tuple[Node, Node]], extra_nodes: Iterable[Node]=()) -> Adjacency:
    """Build an undirected adjacency map covering every node mentioned anywhere."""
    adj: Adjacency = {}
    for n in list(nodes) + list(extra_nodes):
        adj.setdefault(n, set())
    for u, v in edges:
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)
    return adj

def _validate_k(k: int) -> None:
    if not isinstance(k, int) or isinstance(k, bool) or k < 0:
        raise ValueError('k must be a non-negative integer')

def color_graph(nodes: Iterable[Node], edges: Iterable[Tuple[Node, Node]], k: int, precolored: Optional[Dict[Node, int]]=None) -> Optional[Dict[Node, int]]:
    """Return a proper k-coloring of the graph as a dict node -> color in 0..k-1,
    keeping precolored nodes fixed, or None if no such coloring exists."""
    _validate_k(k)
    nodes = list(nodes)
    edges = list(edges)
    fixed: Assignment = dict(precolored or {})
    adj = _build_adjacency(nodes, edges, extra_nodes=fixed.keys())
    if not hole_precoloring_consistent(adj, fixed, k):
        return None
    free: List[Node] = [n for n in adj if n not in fixed]
    result = hole_solve(adj, fixed, free, k, hole_pick_next_node)
    if result is None:
        return None
    return dict(result)

def hole_precoloring_consistent(adj: Adjacency, fixed: Assignment, k: int) -> bool:
    """Return True iff the precolored assignment is usable as a starting point:
    every fixed color lies in range(k) (0 <= c < k), and no two adjacent nodes
    that are both precolored share the same color. Return False otherwise.
    Must not modify its arguments."""
    raise NotImplementedError

def hole_pick_next_node(free: List[Node], assignment: Assignment, adj: Adjacency, k: int) -> Node:
    """Return one node from the non-empty list `free` (uncolored nodes) to color
    next. Must be an element of `free`. The choice is a search-ordering policy
    and affects only speed, never correctness. Must not modify its arguments."""
    raise NotImplementedError

def hole_solve(adj: Adjacency, assignment: Assignment, free: List[Node], k: int, pick: PickFn) -> Optional[Assignment]:
