        self.cycle = list(cycle)
        super().__init__('dependency cycle: ' + ' -> '.join(self.cycle))

def hole_all_packages(graph: dict[str, list[str]]) -> set[str]:
    """Return the set of every package that must appear in the output.

    `graph` maps each declared package to its list of dependency names
    (no duplicates). The result must include every key of `graph` and
    every name appearing in any dependency list, even names that are
    never declared as keys. Must not mutate `graph`.
    """
    raise NotImplementedError

def hole_pick_next(ready: set[str]) -> str:
    """Return the single package from `ready` to install next.

    `ready` is a non-empty set of packages whose dependencies are all
    already installed. The return value must be an element of `ready`.
    The choice must be deterministic and must implement the required
    tie-breaking policy for the output order. Must not mutate `ready`.
    """
    raise NotImplementedError

def hole_find_cycle(stuck: dict[str, list[str]]) -> list[str]:
    """Return one dependency cycle among the packages that cannot be installed.

    `stuck` maps each unplaceable package to the sorted list of its
    dependencies that are also unplaceable. Every key has at least one
    entry in its list, so at least one cycle is guaranteed to exist.
    Return a list of package names that forms a cycle, where each name
    is followed by one of its dependencies, the first name is repeated
    at the end (so the result satisfies result[0] == result[-1]), and
    the result has length at least 2. A self-dependency such as
    {"x": ["x"]} must yield ["x", "x"].
    """
    raise NotImplementedError

def topo_order(deps: Mapping[str, Sequence[str]]) -> list[str]:
    """Return an install order (dependencies first) for `deps`.

    `deps` maps a package name to a sequence of its dependency names.
    Raises TypeError on malformed input and CycleError if the graph
    contains a cycle.
    """
    graph: dict[str, list[str]] = {}
    for pkg, requires in deps.items():
        if not isinstance(pkg, str):
            raise TypeError(f'package name must be str, got {pkg!r}')
        if isinstance(requires, str) or not all((isinstance(r, str) for r in requires)):
            raise TypeError(f'dependencies of {pkg!r} must be a sequence of str')
        graph[pkg] = list(dict.fromkeys(requires))
    nodes = hole_all_packages(graph)
    pending: dict[str, set[str]] = {n: set(graph.get(n, [])) for n in nodes}
    dependents: dict[str, list[str]] = defaultdict(list)
    for n in sorted(nodes):
        for d in pending[n]:
            dependents[d].append(n)
    ready = {n for n, waiting in pending.items() if not waiting}
    order: list[str] = []
    while ready:
